  return (
    <div>
      <h2>Study Materials</h2>

      <input
        placeholder="Enter Subject Code"
        onChange={(e) => setSubject(e.target.value)}
      />

      {materials.map((m) => (
        <div key={m.id}>
          <h4>{m.title}</h4>
          <a href={m.file_url} target="_blank">View</a>
        </div>
      ))}
    </div>
  );
}

export default MaterialsStudent;
